<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,TutorGroup,TrainingSession,TimetableRoom as Room,TimetableStaffWindow as Window,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableFlexibleDay as Day,TimetableGroupBrief as Brief,TimetableCoverAllocation as Cover};
use App\Support\{CentrePlanning as P,CentreTimetable as T,TimetableDuties as D,TimetableCover as C,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class TimetableDutiesTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$admin=User::factory()->create(['role'=>'admin']);$planner=User::factory()->create(['role'=>'manager']);P::grant($admin,1,$planner,0,true);$tutor=User::factory()->create(['role'=>'tutor']);$cover=User::factory()->create(['role'=>'tutor']);$other=User::factory()->create(['role'=>'tutor']);$group=TutorGroup::factory()->create(['tutor_id'=>$tutor->id]);$a=Apprentice::factory()->create(['tutor_group_id'=>$group->id,'tutor_id'=>$tutor->id,'start_date'=>'2026-09-07']);$room=Room::where('site','Doncaster')->first();P::room($admin,1,$room,1,['capacity'=>8,'uses'=>['Teaching','Admin','Review'],'active'=>true]);$room->refresh();$date=today()->addDays(7)->startOfWeek()->addDay()->toDateString();$dates=P::dates($date,2);foreach([$tutor,$cover,$other]as$u){P::windows($admin,1,$u,$dates,ReviewedImports::hash(P::windowSource($u,$dates)),true,'08:00','18:00');}$d=['staff_id'=>$tutor->id,'date'=>$date,'weeks'=>2,'start'=>'09:00','end'=>'16:00','kind'=>'Teaching','site'=>'Doncaster','room_id'=>$room->id,'group_id'=>$group->id,'title'=>'Fictional whole-day class','headcount'=>4];return compact('admin','planner','tutor','cover','other','group','a','room','date','dates','d');}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 private function flex(array $f,?User $who=null):Day {$who??=$f['cover'];D::saveDays($f['planner'],1,$who,$f['planner'],$f['dates'],ReviewedImports::hash(D::preview($who,$f['dates'])),'09:00','16:00');return D::day($who->id,$f['date']);}
 private function plan(array $f,?array $data=null):Plan {$p=P::save($f['planner'],1,null,0,(string)Str::uuid(),$data??$f['d']);P::check($f['planner'],1,$p,1,true);P::publish($f['planner'],1,$p->refresh(),2);return $p->refresh();}
 private function proposal(array $f):Cover {$p=$this->plan($f);$day=$this->flex($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();return C::prepare($f['planner'],1,$e,$day,(string)Str::uuid(),'PRIVATE-SUITABILITY-REFERENCE');}
 private function activate(array $f):Cover {$c=$this->proposal($f);C::check($f['planner'],1,$c,1);C::publish($f['planner'],1,$c->refresh(),2);return $c->refresh();}
 public function test_group_count_and_earliest_start_are_derived_without_inventing_group_start():void {$f=$this->fixture();$x=D::facts($f['group']->id);$this->assertSame(1,$x['count']);$this->assertNull($x['start']);$this->assertSame('2026-09-07',$x['earliest_apprentice_start']);$this->assertSame('Group start not recorded',$x['start_label']);$this->assertNull($x['notes']);}
 public function test_group_brief_is_encrypted_current_and_does_not_rewrite_members_or_dates():void {$f=$this->fixture();D::brief($f['planner'],1,$f['group'],0,'2026-09-01','SHARED-OPERATIONAL-NOTE');$this->assertSame('Recorded group start',D::facts($f['group']->id)['start_label']);$this->assertSame('2026-09-07',$f['a']->fresh()->start_date->toDateString());$this->assertStringNotContainsString('SHARED-OPERATIONAL',DB::table('timetable_group_briefs')->value('details'));$this->assertDatabaseCount('apprentices',1);}
 public function test_stale_group_brief_and_tamper_are_held():void {$f=$this->fixture();D::brief($f['planner'],1,$f['group'],0,null,'First');$this->reject(fn()=>D::brief($f['planner'],1,$f['group'],0,null,'Stale'));DB::table('timetable_group_briefs')->update(['version'=>9]);$this->assertNull(D::facts($f['group']->id)['notes']);$this->assertFalse(D::facts($f['group']->id)['brief_current']);}
 public function test_normal_staff_cannot_edit_or_read_planner_group_pages():void {$f=$this->fixture();foreach(['/centre-planning/group-details','/centre-planning/flexible-duties','/centre-planning/cover']as$url){$this->actingAs($f['cover'])->get($url)->assertForbidden();}$this->post('/centre-planning/group-details/'.$f['group']->id,['version'=>0,'notes'=>'PRIVATE','confirmed'=>1])->assertForbidden();}
 public function test_flexible_day_classification_preserves_working_time_and_does_not_book_away_day():void {$f=$this->fixture();$before=Window::get()->toArray();$day=$this->flex($f);$this->assertTrue(D::dayCurrent($day));$this->assertSame($before,Window::get()->toArray());$this->assertSame([],P::busy([$f['date']])['rows']);$b=T::board($f['cover'],$f['date']);$c=$b['cells'][$f['cover']->id][$f['date']];$this->assertSame(600,$c['stats']['available']);$this->assertTrue($c['flexible_current']);$this->assertStringContainsString('not a guaranteed non-teaching day',D::POLICY);}
 public function test_gap_labels_split_regular_and_flexible_duties_without_losing_minutes():void {$f=$this->fixture();$this->flex($f);$x=D::gapParts($f['cover']->id,$f['date'],480,1080);$this->assertSame([[480,540,'Available'],[540,960,'Flexible duties — unallocated'],[960,1080,'Available']],$x);$this->assertSame(600,array_sum(array_map(fn($r)=>$r[1]-$r[0],$x)));}
 public function test_exact_flexible_preview_rejects_stale_overwrite():void {$f=$this->fixture();$hash=ReviewedImports::hash(D::preview($f['cover'],$f['dates']));$this->flex($f);$this->reject(fn()=>D::saveDays($f['planner'],1,$f['cover'],$f['planner'],$f['dates'],$hash,'10:00','16:00'));$this->assertDatabaseCount('timetable_flexible_days',2);}
 public function test_missing_working_window_or_bad_owner_cannot_classify_day():void {$f=$this->fixture();$outsider=User::factory()->create(['role'=>'tutor']);$this->reject(fn()=>D::saveDays($f['planner'],1,$outsider,$f['planner'],$f['dates'],ReviewedImports::hash(D::preview($outsider,$f['dates'])),'09:00','16:00'));$this->reject(fn()=>D::saveDays($f['planner'],1,$f['cover'],$f['other'],$f['dates'],ReviewedImports::hash(D::preview($f['cover'],$f['dates'])),'09:00','16:00'));}
 public function test_window_or_manager_authority_change_invalidates_current_day():void {$f=$this->fixture();$day=$this->flex($f);P::windows($f['admin'],1,$f['cover'],$f['dates'],ReviewedImports::hash(P::windowSource($f['cover'],$f['dates'])),true,'08:00','17:00');$this->assertFalse(D::dayCurrent($day->refresh()));$day=$this->flex($f);P::grant($f['admin'],1,$f['planner'],1,false);$this->assertFalse(D::dayCurrent($day->refresh()));}
 public function test_withdrawing_classification_keeps_booked_work():void {$f=$this->fixture();$day=$this->flex($f);$d=array_replace($f['d'],['staff_id'=>$f['cover']->id,'kind'=>'Marking','group_id'=>null,'room_id'=>null,'headcount'=>null,'site'=>'Remote','start'=>'10:00','end'=>'11:00']);$this->plan($f,$d);D::withdrawDay($f['planner'],1,$day,1);$this->assertFalse(D::dayCurrent($day->refresh()));$this->assertCount(1,P::busy([$f['date']])['rows']);}
 public function test_all_new_duties_use_existing_checked_planning_and_do_not_complete_tasks():void {$f=$this->fixture();foreach(D::OTHER_TYPES as$i=>$kind){$d=array_replace($f['d'],['staff_id'=>$f['cover']->id,'kind'=>$kind,'group_id'=>null,'headcount'=>null,'start'=>sprintf('%02d:00',9+$i),'end'=>sprintf('%02d:00',10+$i)]);$this->assertTrue(P::published($this->plan($f,$d)));}$this->assertDatabaseCount('learning_tasks',0);$this->assertDatabaseCount('signed_review_records',0);}
 public function test_cover_draft_not_visible_or_reserved_and_request_replay_exact():void {$f=$this->fixture();$c=$this->proposal($f);$this->assertTrue(C::intact($c));$this->assertFalse(C::active($c));$rows=P::busy([$f['date']])['rows'];$this->assertCount(1,$rows);$this->assertSame($f['tutor']->id,$rows[0]['staff_id']);$again=C::prepare($f['planner'],1,Entry::find($c->entry_id),Day::find($c->flexible_day_id),$c->request_token,'PRIVATE-SUITABILITY-REFERENCE');$this->assertSame($c->id,$again->id);}
 public function test_cover_needs_different_tutor_and_whole_current_day():void {$f=$this->fixture();$p=$this->plan($f);$e=Entry::where('plan_id',$p->id)->first();$day=$this->flex($f,$f['tutor']);$this->reject(fn()=>C::prepare($f['planner'],1,$e,$day,(string)Str::uuid(),'Ref'));$day=$this->flex($f);D::saveDays($f['planner'],1,$f['cover'],$f['planner'],$f['dates'],ReviewedImports::hash(D::preview($f['cover'],$f['dates'])),'10:00','16:00');$this->reject(fn()=>C::prepare($f['planner'],1,$e,$day->refresh(),(string)Str::uuid(),'Ref'));}
 public function test_checked_cover_moves_one_planned_occurrence_not_permanent_tutor_or_register_permissions():void {$f=$this->fixture();$c=$this->activate($f);$this->assertTrue(C::current($c));$rows=P::busy([$f['date']])['rows'];$this->assertCount(1,$rows);$this->assertSame($f['cover']->id,$rows[0]['staff_id']);$this->assertSame($f['tutor']->id,$f['group']->refresh()->tutor_id);$this->assertSame($f['tutor']->id,$f['a']->refresh()->tutor_id);$this->assertSame($f['tutor']->id,P::busy([$f['dates'][1]])['rows'][0]['staff_id']);$this->actingAs($f['cover'])->get('/apprentices/'.$f['a']->id)->assertForbidden();}
 public function test_no_implicit_register_access_for_planning_cover():void {$f=$this->fixture();$c=$this->activate($f);$s=TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>$f['date'],'start_time'=>'09:00','end_time'=>'16:00','members'=>[$f['a']->id]]);$this->actingAs($f['cover'])->get('/sessions/'.$s->id)->assertForbidden();$this->assertFalse(C::current($c->refresh()));$this->assertGreaterThanOrEqual(2,count(P::busy([$f['date']])['rows']));}
 public function test_cover_on_original_nonworking_day_is_allowed_without_changing_absence_window():void {$f=$this->fixture();$c=$this->proposal($f);P::windows($f['admin'],1,$f['tutor'],$f['dates'],ReviewedImports::hash(P::windowSource($f['tutor'],$f['dates'])),false,null,null);C::check($f['planner'],1,$c,1);C::publish($f['planner'],1,$c->refresh(),2);$this->assertTrue(C::current($c->refresh()));$this->assertFalse(Window::where('user_id',$f['tutor']->id)->first()->working);}
 public function test_cover_publish_requires_check_and_expected_version():void {$f=$this->fixture();$c=$this->proposal($f);$this->reject(fn()=>C::publish($f['planner'],1,$c,1));C::check($f['planner'],1,$c,1);$this->reject(fn()=>C::publish($f['planner'],1,$c->refresh(),1));}
 public function test_cover_rejects_conflicting_work_and_competing_cover():void {$f=$this->fixture();$c=$this->proposal($f);$d=array_replace($f['d'],['staff_id'=>$f['cover']->id,'kind'=>'Marking','group_id'=>null,'headcount'=>null,'room_id'=>null,'site'=>'Remote','start'=>'10:00','end'=>'11:00']);$this->plan($f,$d);$this->reject(fn()=>C::check($f['planner'],1,$c,1));}
 public function test_another_active_cover_for_same_class_is_blocked():void {$f=$this->fixture();$c=$this->activate($f);$day=$this->flex($f,$f['other']);$other=C::prepare($f['planner'],1,Entry::find($c->entry_id),$day,(string)Str::uuid(),'Other suit reference');$this->reject(fn()=>C::check($f['planner'],1,$other,1));$this->assertSame(1,Cover::whereNotNull('active_entry_id')->count());}
 public function test_changed_class_membership_or_room_holds_cover_source():void {$f=$this->fixture();$c=$this->proposal($f);Apprentice::factory()->create(['tutor_group_id'=>$f['group']->id]);$this->reject(fn()=>C::check($f['planner'],1,$c,1));}
 public function test_cover_drift_reserves_both_original_and_cover_until_reconciled():void {$f=$this->fixture();$c=$this->activate($f);$day=Day::find($c->flexible_day_id);D::withdrawDay($f['planner'],1,$day,1);$rows=P::busy([$f['date']])['rows'];$this->assertFalse(C::current($c->refresh()));$this->assertContains($f['tutor']->id,array_column($rows,'staff_id'));$this->assertContains($f['cover']->id,array_column($rows,'staff_id'));$this->assertSame(1,count(array_filter($rows,fn($r)=>$r['kind']==='Cover hold')));}
 public function test_cover_withdrawal_restores_original_planning_and_keeps_data():void {$f=$this->fixture();$c=$this->activate($f);C::withdraw($f['planner'],1,$c,3,'Reconciled');$this->assertTrue(C::closed($c->refresh()));$rows=P::busy([$f['date']])['rows'];$this->assertCount(1,$rows);$this->assertSame($f['tutor']->id,$rows[0]['staff_id']);$this->assertDatabaseCount('timetable_plans',1);}
 public function test_cover_from_another_week_never_creates_ghost_holds_in_empty_week():void {$f=$this->fixture();$c=$this->activate($f);D::withdrawDay($f['planner'],1,Day::find($c->flexible_day_id),1);$this->assertSame([],P::busy([today()->addMonths(3)->toDateString()])['rows']);}
 public function test_unlinked_or_marked_register_blocks_cover_but_checked_link_is_preserved():void {$f=$this->fixture();$p=$this->plan($f);$day=$this->flex($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();$s=TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>$f['date'],'start_time'=>'09:00','end_time'=>'16:00','members'=>[$f['a']->id]]);$this->reject(fn()=>C::prepare($f['planner'],1,$e,$day,(string)Str::uuid(),'Ref'));P::link($f['planner'],1,$e,3,$s,1);$c=C::prepare($f['planner'],1,$e->refresh(),$day,(string)Str::uuid(),'Checked original register arrangements');C::check($f['planner'],1,$c,1);C::publish($f['planner'],1,$c->refresh(),2);$this->assertCount(1,P::busy([$f['date']])['rows']);$this->assertSame($s->id,$e->refresh()->training_session_id);$this->assertSame($f['tutor']->id,$s->group->tutor_id);}
 public function test_forged_cover_state_and_active_pointer_fail_closed():void {$f=$this->fixture();$c=$this->proposal($f);DB::table('timetable_cover_allocations')->update(['state'=>'Active','active_entry_id'=>$c->entry_id]);$this->assertFalse(C::active($c->refresh()));$this->assertNotEmpty(P::busy([$f['date']])['uncertain']);}
 public function test_required_event_failure_rolls_back_cover_publication():void {$f=$this->fixture();$c=$this->proposal($f);C::check($f['planner'],1,$c,1);AuditFault::install('cover_fault','timetable_duty_events','Fictional failure','cover_published');try{C::publish($f['planner'],1,$c->refresh(),2);$this->fail('Expected audit failure');}catch(\Illuminate\Database\QueryException){$this->assertSame('Draft',$c->refresh()->state);$this->assertNull($c->active_entry_id);}}
 public function test_flexible_multi_date_event_failure_is_atomic():void {$f=$this->fixture();AuditFault::install('flex_fault','timetable_duty_events','Fictional failure','flexible_day_saved');try{$this->flex($f);$this->fail('Expected event failure');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('timetable_flexible_days',0);}}
 public function test_policy_pattern_counts_covered_flexible_day_once_and_never_claims_contractual_compliance():void {$f=$this->fixture();$c=$this->activate($f);$x=D::pattern($f['cover']->id,[$f['date']],P::busy([$f['date']])['rows']);$this->assertSame(1,$x['flexible_duties_days']);$this->assertSame(0,$x['ordinary_teaching_days']);$this->assertFalse($x['contractual_compliance_inferred']);}
 public function test_day_cards_show_shared_details_and_escape_note_markup():void {$f=$this->fixture();D::brief($f['planner'],1,$f['group'],0,'2026-09-01','<script>no-run</script> Shared workshop note');$this->plan($f);$this->actingAs($f['planner'])->get('/centre-planning?week='.$f['date'])->assertOk()->assertSee('planning-compact')->assertSee('Recorded group start')->assertSee('currently allocated')->assertSee('&lt;script&gt;',false)->assertDontSee('<script>no-run</script>',false);}
 public function test_all_new_planner_forms_render_and_staff_only_own_board_remains():void {$f=$this->fixture();$c=$this->activate($f);$this->actingAs($f['planner']);foreach(['/centre-planning/group-details','/centre-planning/flexible-duties?staff_id='.$f['cover']->id.'&date='.$f['date'],'/centre-planning/cover','/centre-planning/cover/'.$c->id]as$url){$this->get($url)->assertOk()->assertHeader('Referrer-Policy','no-referrer');}$this->actingAs($f['cover'])->get('/centre-planning?week='.$f['date'])->assertOk()->assertSee('Flexible Duties Day')->assertDontSee('PRIVATE-SUITABILITY-REFERENCE');}
 public function test_cover_does_not_create_actual_delivery_signoff_otj_or_messages():void {Mail::fake();Http::preventStrayRequests();$f=$this->fixture();$this->activate($f);foreach(['training_sessions','attendance_marks','historical_otj_records','signed_review_records']as$t){$this->assertDatabaseCount($t,0);}Mail::assertNothingSent();Http::assertNothingSent();}
 public function test_shared_group_enrichment_does_not_invalidate_existing_published_plan_snapshot():void {$f=$this->fixture();$p=$this->plan($f);$hash=$p->source_hash;D::brief($f['planner'],1,$f['group'],0,'2026-09-01','Workshop operational note');$this->assertTrue(P::fresh($p->refresh()));$this->assertSame($hash,$p->source_hash);}
 public function test_day_cards_use_weekdays_but_keep_a_weekend_flexible_allocation_visible():void {$f=$this->fixture();$normal=T::board($f['cover'],$f['date'],'staff',null,null,true);$this->assertCount(5,$normal['dates']);$date=\Carbon\Carbon::parse($f['date'])->startOfWeek()->addDays(5)->toDateString();P::windows($f['planner'],1,$f['cover'],[$date],ReviewedImports::hash(P::windowSource($f['cover'],[$date])),true,'09:00','16:00');D::saveDays($f['planner'],1,$f['cover'],$f['planner'],[$date],ReviewedImports::hash(D::preview($f['cover'],[$date])),'09:00','16:00');$b=T::board($f['cover'],$date,'staff',null,null,true);$this->assertCount(7,$b['dates']);$this->assertTrue($b['cells'][$f['cover']->id][$date]['flexible_current']);}
 public function test_timezone_change_holds_cover_and_retains_original_and_cover_reservations():void {$f=$this->fixture();$c=$this->activate($f);config(['app.timezone'=>'America/New_York']);$this->assertFalse(C::current($c));$rows=P::busy([$f['date']])['rows'];$this->assertContains($f['tutor']->id,array_column($rows,'staff_id'));$this->assertContains($f['cover']->id,array_column($rows,'staff_id'));}

}
